def append_dedup(rows, path):
    with open(path, 'a', encoding='utf-8') as f:
        existing = set(line.strip() for line in f)
        for row in rows:
            clean_row = row.strip()
            if clean_row and clean_row not in existing:
                f.write(f'{clean_row}\n')
                existing.add(clean_row)
