def save_nested(rows, root):
    os.makedirs(os.path.join(root, 'a', 'b'), exist_ok=True)
    for i, row in enumerate(range(0, len(rows), 4)):
        with open(os.path.join(root, 'a', 'b', f'p{str(i).zfill(2)}.txt'), 'w', encoding='utf-8') as f:
            for item in rows[row:row+4]:
                f.write(item.strip() + '\n')
